python3 -c "
import json
d = json.load(open('/app/trial/agent/trajectory.json'))
steps = d['steps']
for i, s in enumerate(steps):
    msg = s.get('message')
    tcs = s.get('tool_calls')
    if tcs:
        for tc in tcs:
            name = tc.get('name') or tc.get('tool_name')
            args = tc.get('arguments') or tc.get('input') or {}
            argstr = json.dumps(args)[:200]
            print(f'{i} TOOLCALL {name} {argstr}')
    if isinstance(msg, str) and msg.strip():
        print(f'{i} MSG: {msg[:300]}')
"

